//! Literal connected Tape AudioHandler stage-tail policy. No DSP/curve preparation.
//! Input silence is authoritative metadata, never inferred from numeric PCM.
#[path="../../rack-native/src/tail.rs"]mod tail;
#[cfg(feature="allocation-audit")]mod allocation;
const MAX_FRAME:f64=1099511627648.;const INVALID:u32=u32::MAX;
pub struct Policy{rate:f64,last_frame:Option<u64>,pending:bool,frame:u64,connected:bool,silent:[bool;3],enabled:[bool;3],tail_pending:[bool;3],input_active:Option<bool>,mode:[u32;3],last_non_silent:[f64;3],tail:[f64;3],latency:[f64;3],body:[u64;3],params:[u64;3],unpulled:u64,calls:u64,rejected:u64,last_tone:f64}
fn canonical(f:f64)->bool{f.is_finite()&&f>=0.&&f<=MAX_FRAME&&f.fract()==0.&&f%128.==0.}
fn boolean(v:f64)->Option<bool>{if v==0.{Some(false)}else if v==1.{Some(true)}else{None}}
fn coefficients(rate:f64,frequency:f64)->[f64;5]{let f=frequency.clamp(0.,rate*0.5)/(rate*0.5);if f>=1.{return[1.,0.,0.,0.,0.];}if f<=0.{return[0.;5];}let resonance=(((0.5f64/20.)*std::f64::consts::LN_10)as f32).exp()as f64;let theta=std::f64::consts::PI*f;let alpha=theta.sin()/(2.*resonance);let cosine=theta.cos();let beta=(1.-cosine)/2.;let norm=1.+alpha;[beta/norm,2.*beta/norm,beta/norm,-2.*cosine/norm,(1.-alpha)/norm]}
impl Policy{
 pub fn new(rate:f64)->Option<Box<Self>>{if !rate.is_finite()||rate.fract()!=0.||!(8000. ..=192000.).contains(&rate){return None;}Some(Box::new(Self{rate,last_frame:None,pending:false,frame:0,connected:false,silent:[true;3],enabled:[true;3],tail_pending:[false;3],input_active:None,mode:[0;3],last_non_silent:[0.;3],tail:[0.,f64::INFINITY,0.02],latency:[128./rate,0.,0.],body:[0;3],params:[0;3],unpulled:0,calls:0,rejected:0,last_tone:f64::NAN}))}
 fn reject(&mut self)->u32{self.rejected+=1;INVALID}
 pub fn begin(&mut self,frame:f64,input_silent:bool,input_active:bool,connected:bool)->u32{if self.pending||!input_active&&!input_silent||!canonical(frame)||self.last_frame.is_some_and(|last|frame<last as f64+128.){return self.reject();}self.frame=frame as u64;self.connected=connected;self.silent[0]=input_silent;let time=frame/self.rate;if input_active{self.enabled=[true;3];self.tail_pending=[false;3];}else{if self.input_active!=Some(false){self.tail_pending[0]=true;}for i in 0..3{if i>0&&!self.enabled[i-1]{self.tail_pending[i]=true;}if self.tail_pending[i]&&self.last_non_silent[i]+self.latency[i]+self.tail[i]<time{self.enabled[i]=false;self.tail_pending[i]=false;}}}self.input_active=Some(input_active);if !connected||!self.enabled[2]{self.mode=[0;3];}else{for i in 0..3{if i>0{self.silent[i]=self.mode[i-1]!=2;}let propagates=self.last_non_silent[i]+self.latency[i]+self.tail[i]<time;self.mode[i]=if !self.enabled[i]{0}else if self.silent[i]&&propagates{1}else{2};}}self.pending=true;let mut mask=0;for i in 0..3{mask|=self.mode[i]<<(2*i);}if connected&&self.enabled[2]{for i in 3..11{mask|=2<<(2*i);}}mask}
 pub fn finish(&mut self,tone:f64)->bool{if !self.pending||!tone.is_finite()||tone<0.||tone>self.rate*0.5||tone!=tone as f32 as f64{self.rejected+=1;return false;}if self.connected&&self.enabled[2]{for i in 0..3{if self.mode[i]!=0&&!self.silent[i]{self.last_non_silent[i]=(self.frame+128)as f64/self.rate;}if self.mode[i]==2{self.body[i]+=128;}else if self.mode[i]==1{self.params[i]+=128;}}if self.mode[1]==2{self.tail[1]=tail::tail_frame(coefficients(self.rate,tone),30.*self.rate)/self.rate;self.last_tone=tone;}}else{self.unpulled+=128;}self.pending=false;self.last_frame=Some(self.frame);self.calls+=1;true}
}
#[no_mangle]pub extern "C" fn tape_stage_policy_api()->u32{2}
#[no_mangle]pub extern "C" fn tape_stage_policy_new(rate:f64)->*mut Policy{Policy::new(rate).map(Box::into_raw).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub unsafe extern "C" fn tape_stage_policy_free(p:*mut Policy){if !p.is_null(){drop(Box::from_raw(p));}}
#[no_mangle]pub extern "C" fn tape_stage_policy_begin(p:&mut Policy,frame:f64,silent:f64,active:f64,connected:f64)->u32{let(Some(s),Some(a),Some(c))=(boolean(silent),boolean(active),boolean(connected))else{return p.reject();};p.begin(frame,s,a,c)}
#[no_mangle]pub extern "C" fn tape_stage_policy_finish(p:&mut Policy,tone:f64)->u32{p.finish(tone)as u32}
#[no_mangle]pub extern "C" fn tape_stage_policy_stat(p:&Policy,key:u32)->f64{match key{0=>p.frame as f64,1=>p.calls as f64,2=>p.rejected as f64,3=>p.pending as u32 as f64,4=>p.unpulled as f64,5=>p.last_tone,6..=8=>p.last_non_silent[(key-6)as usize],9..=11=>p.tail[(key-9)as usize],12..=14=>p.body[(key-12)as usize]as f64,15..=17=>p.params[(key-15)as usize]as f64,18..=20=>p.mode[(key-18)as usize]as f64,21..=23=>p.enabled[(key-21)as usize]as u32 as f64,_=>f64::NAN}}
